const snoozeMemory = `-- name: SnoozeMemory :exec
UPDATE memories
SET last_reviewed_at = $1::timestamptz,
    review_count = review_count + 1,
    next_review_at = $2::timestamptz,
    resurface_muted = false,
    updated_by_user_id = $3,
    updated_at = $4::timestamptz
WHERE tenant_id = $5 AND id = $6
`

type SnoozeMemoryParams struct {
	Now          time.Time
	NextReviewAt time.Time
	Actor        *uuid.UUID
	UpdatedAt    time.Time
	TenantID     uuid.UUID
	ID           uuid.UUID
}

// The Fluent read-modify-write of MeBriefService.feedback in one statement:
// lastReviewedAt = now, reviewCount += 1, applyReviewAction(.later),
// updatedByUserID, and Fluent's updated_at timestamp.
func (q *Queries) SnoozeMemory(ctx context.Context, arg SnoozeMemoryParams) error {
	_, err := q.db.Exec(ctx, snoozeMemory,
		arg.Now,
		arg.NextReviewAt,
		arg.Actor,
		arg.UpdatedAt,
		arg.TenantID,
		arg.ID,
	)
	return err
}

const streakDays = `-- name: StreakDays :one
WITH activity_days AS (
    SELECT DISTINCT (created_at AT TIME ZONE $1::text)::date AS day
    FROM memories
    WHERE tenant_id = $2::uuid
    UNION
    SELECT DISTINCT (created_at AT TIME ZONE $1::text)::date AS day
    FROM conversations
    WHERE tenant_id = $2::uuid
),
bounded AS (
    SELECT day FROM activity_days
    WHERE day <= $3::text::date
),
ranked AS (
    SELECT day,
           day - (row_number() OVER (ORDER BY day))::int AS island_key
    FROM bounded
),
latest AS (
    SELECT island_key
    FROM ranked
    WHERE day >= $3::text::date - 1
    ORDER BY day DESC
    LIMIT 1
)
SELECT COUNT(*)::int AS count
FROM ranked
WHERE island_key = (SELECT island_key FROM latest)
`

type StreakDaysParams struct {
	Tz       string
	TenantID uuid.UUID
	AsOfDay  string
}

// DashboardController.currentStreakDays with asOfDay.
func (q *Queries) StreakDays(ctx context.Context, arg StreakDaysParams) (int32, error) {
	row := q.db.QueryRow(ctx, streakDays, arg.Tz, arg.TenantID, arg.AsOfDay)
	var count int32
	err := row.Scan(&count)
	return count, err
}

